// Copies a reply as HTML and as text, as the reference's copy button does:
// the rendered message is cloned, stripped of app attributes and controls,
// and serialized next to the reply's Markdown.
export async function copyMessage(article: HTMLElement, reply: { markdown: string; messageId: string }, telemetry: any) {
	const clone = article.querySelector('.lm-reply')!.cloneNode(true) as HTMLElement;
	for (const element of clone.querySelectorAll('button, svg, .lm-sr-only'))
		element.remove();
	for (const element of clone.querySelectorAll('*')) {
		for (const name of element.getAttributeNames()) {
			if (name.startsWith('data-') || name === 'class' || name === 'style')
				element.removeAttribute(name);
		}
	}
	const html = `<meta charset="utf-8">${clone.innerHTML}`;
	const text = reply.markdown || clone.textContent || '';
	const item = new ClipboardItem({ 'text/html': new Blob([html], { type: 'text/html' }), 'text/plain': new Blob([text], { type: 'text/plain' }) });
	await navigator.clipboard.write([item]);
	telemetry.business('message_copied', { message: reply.messageId, chars: text.length, html: html.length });
}
