// When a reply is done: its stream has ended and every code block shows the
// highlighting of its latest source. Highlighting is asynchronous (the
// highlighter and its grammars load on first use, and each revision of a
// growing block is highlighted again), so the stream's final line can arrive
// before the last highlight is committed. The app announces the reply with
// the "reply-complete" signal from the commit that completes it, which is
// what the benchmark steps await.
import { env } from '../app/env.ts';

let highlighting = 0;
let streamEnded = false;

function check() {
	if (streamEnded && highlighting === 0) {
		streamEnded = false;
		env.signal('reply-complete');
	}
}

// A code block started highlighting a source.
export function highlightStarted() {
	highlighting++;
}

// A highlight was committed to the DOM (from the code block's layout effect),
// or was dropped because its block moved on to another source.
export function highlightSettled() {
	highlighting--;
	check();
}

// The stream's final line has been applied and committed.
export function streamFinished() {
	streamEnded = true;
	check();
}
