// The conversation's state, an external store the components subscribe to
// with useSyncExternalStore. Every change replaces the snapshot.
export type Reply = {
	seq: number;
	tree: any;
	words: number;
	seenWords: number;
	markdown: string;
	widgets: any[];
	status: 'waiting' | 'streaming' | 'done';
	messageId: string;
};

export type Turn = { id: string; prompt: string; reply: Reply };

export type ConversationState = {
	threadId: string | null;
	path: string | null;
	turns: Turn[];
	streaming: boolean;
	phase: string;
	suggestions: number;
	timing: { firstTokenMs: number; durationMs: number } | null;
};

const EMPTY: ConversationState = { threadId: null, path: null, turns: [], streaming: false, phase: 'idle', suggestions: 0, timing: null };

export class ConversationStore {
	#state = EMPTY;
	#listeners = new Set<() => void>();

	subscribe = (listener: () => void) => {
		this.#listeners.add(listener);
		return () => this.#listeners.delete(listener);
	};

	getSnapshot = () => this.#state;

	update(change: Partial<ConversationState>) {
		this.#state = { ...this.#state, ...change };
		for (const listener of this.#listeners)
			listener();
	}

	updateTurn(id: string, change: (turn: Turn) => Turn) {
		this.update({ turns: this.#state.turns.map((turn) => (turn.id === id ? change(turn) : turn)) });
	}

	addTurn(prompt: string) {
		const id = `turn-${this.#state.turns.length}`;
		const reply: Reply = { seq: 0, tree: null, words: 0, seenWords: 0, markdown: '', widgets: [], status: 'waiting', messageId: '' };
		this.update({ turns: [...this.#state.turns, { id, prompt, reply }], streaming: true, phase: 'sending' });
		return id;
	}

	reset() {
		this.update(EMPTY);
	}
}

export const conversation = new ConversationStore();

