// Sends a prompt and reads the reply's NDJSON stream: control signals,
// partial updates for server-owned HTML, and cumulative revisions of the
// reply program, which go to the generated-UI worker. A revision's tree is
// applied once the worker's result is decoded, in sequence order.
import { applyPatchHTML } from '../partial-updates/index.js';
import { env } from '../app/env.ts';
import { conversation } from './store.ts';
import { evaluateInWorker } from '../genui/client.ts';
import { countWords, prepareTree } from '../genui/words.ts';

export type StreamHooks = {
	// Resolves once the thread's route is mounted: the stream's later
	// partial updates target its slots.
	onThread(path: string): Promise<void> | void;
	onRevision(): void;
	onComplete(): void;
	telemetry: any;
};

async function postJSON(url: string, body: object) {
	const response = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
	return response.json();
}

export async function sendPrompt(prompt: string, hooks: StreamHooks) {
	const turnId = conversation.addTurn(prompt);
	const state = conversation.getSnapshot();
	hooks.telemetry.business('prompt_submitted', { length: prompt.length, turn: state.turns.length, thread: state.threadId });
	const prepared = await postJSON('api/conversation/prepare', { prompt_length: prompt.length, thread: state.threadId, client: { tz: 'UTC', locale: 'en-US' } });
	const requirements = await postJSON('api/conversation/requirements', { conduit: prepared.conduit, persona: 'anonymous' });
	const response = await fetch('api/conversation', {
		method: 'POST',
		headers: { accept: 'application/x-ndjson', 'content-type': 'application/json', 'x-requirements': requirements.token },
		body: JSON.stringify({ action: 'next', thread: state.threadId, messages: [{ role: 'user', content: prompt }], model: prepared.model, conduit: prepared.conduit }),
	});
	const reader = response.body!.getReader();
	const decoder = new TextDecoder();
	let buffer = '';
	let applied = Promise.resolve();
	for (;;) {
		const { value, done } = await reader.read();
		if (done)
			break;
		buffer += decoder.decode(value, { stream: true });
		let newline;
		while ((newline = buffer.indexOf('\n')) >= 0) {
			const text = buffer.slice(0, newline);
			buffer = buffer.slice(newline + 1);
			if (!text)
				continue;
			const line = JSON.parse(text);
			// Revisions and the lines after them apply in order once the
			// worker's results are in.
			applied = applied.then(() => handleLine(line, turnId, hooks));
		}
	}
	await applied;
}

async function handleLine(line: any, turnId: string, hooks: StreamHooks) {
	switch (line.kind) {
		case 'signal':
			if (line.name === 'thread') {
				conversation.update({ threadId: line.threadId, path: line.path });
				await hooks.onThread(line.path);
			} else if (line.name === 'reply-started') {
				conversation.updateTurn(turnId, (turn) => ({ ...turn, reply: { ...turn.reply, messageId: line.messageId, status: 'streaming' } }));
				conversation.update({ phase: 'streaming' });
			} else if (line.name === 'timing') {
				hooks.telemetry.performance('reply_timing', { firstTokenMs: line.firstTokenMs });
			} else if (line.name === 'final') {
				finish(turnId, hooks);
			}
			break;
		case 'status':
			conversation.update({ phase: line.phase });
			break;
		case 'patch':
			applyPatchHTML(line.html, document.body);
			break;
		case 'revision': {
			const { seq, tree } = await evaluateInWorker(line);
			conversation.updateTurn(turnId, (turn) => ({
				...turn,
				reply: { ...turn.reply, seq, tree: prepareTree(turn.reply.tree, tree), words: countWords(tree), seenWords: turn.reply.words, markdown: line.markdown, widgets: line.widgets },
			}));
			hooks.onRevision();
			break;
		}
		case 'end':
			break;
	}
}

function finish(turnId: string, hooks: StreamHooks) {
	conversation.updateTurn(turnId, (turn) => ({ ...turn, reply: { ...turn.reply, status: 'done' } }));
	conversation.update({ streaming: false, phase: 'done' });
	// The fade-in of the last words ends with their animation; the benchmark
	// commits it at the end of the step.
	env.onFlush(() => conversation.updateTurn(turnId, (turn) => ({ ...turn, reply: { ...turn.reply, seenWords: turn.reply.words } })));
	hooks.onComplete();
}
